Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$Root = (Get-Location).Path
$ExpectedBranch = "feature/vitrine-marketplace"
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$RelativePath = "components\food\DeliveriesManager.tsx"
$Source = Join-Path $Root $RelativePath
$Backup = "$Source.command-center-$Timestamp.backup"

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
    throw "Execute este script na raiz do projeto Orçaly."
}

$Branch = (& git branch --show-current | Out-String).Trim()

if ($Branch -ne $ExpectedBranch) {
    throw "Branch atual: $Branch. Use $ExpectedBranch."
}

if (-not (Test-Path -LiteralPath $Source)) {
    throw "Arquivo não encontrado: $RelativePath"
}

Copy-Item -LiteralPath $Source -Destination $Backup -Force

function Restore-DeliveriesBackup {
    Write-Host ""
    Write-Host "Restaurando a tela anterior de entregas..." -ForegroundColor Yellow

    if (Test-Path -LiteralPath $Backup) {
        Copy-Item -LiteralPath $Backup -Destination $Source -Force
    }
}

try {
    $EncodedContent = @'

'@

    $Bytes = [Convert]::FromBase64String(($EncodedContent -replace "\s", ""))
    [IO.File]::WriteAllBytes($Source, $Bytes)

    Write-Host "==> Aplicando nova central de entregas" -ForegroundColor Cyan

    $Checks = @(
        "ORCALY_DELIVERIES_COMMAND_CENTER_V1",
        "Central de entregas",
        "Operação ativa",
        "Quadro",
        "Lista",
        "Nova entrega",
        "Aguardando preparo",
        "Saiu para entrega",
        "Confirmar entrega",
        "Cadastrar entrega"
    )

    foreach ($Text in $Checks) {
        $Found = Select-String `
            -LiteralPath $Source `
            -Pattern $Text `
            -SimpleMatch `
            -ErrorAction SilentlyContinue

        if (-not $Found) {
            throw "Verificação falhou: $Text"
        }

        Write-Host "[OK] $Text" -ForegroundColor Green
    }

    Write-Host ""
    Write-Host "==> Verificando diff" -ForegroundColor Cyan

    git --no-pager diff --check -- $RelativePath

    if ($LASTEXITCODE -ne 0) {
        throw "git diff --check encontrou problemas."
    }

    Remove-Item `
        -LiteralPath (Join-Path $Root ".next") `
        -Recurse `
        -Force `
        -ErrorAction SilentlyContinue

    Write-Host ""
    Write-Host "==> Executando build completo" -ForegroundColor Cyan

    npm run build
    $BuildExitCode = $LASTEXITCODE

    Write-Host ""
    Write-Host "BUILD_EXIT_CODE=$BuildExitCode" -ForegroundColor Yellow

    if ($BuildExitCode -ne 0) {
        throw "O build falhou."
    }

    Remove-Item -LiteralPath $Backup -Force

    Write-Host ""
    Write-Host "==================================================" -ForegroundColor Green
    Write-Host "CENTRAL DE ENTREGAS REPAGINADA" -ForegroundColor Green
    Write-Host "==================================================" -ForegroundColor Green
    Write-Host "Quadro operacional por etapas"
    Write-Host "Lista completa e responsiva"
    Write-Host "Busca e filtros rápidos"
    Write-Host "Indicadores de operação e atrasos"
    Write-Host "Formulário em painel lateral"
    Write-Host "Ações rápidas de rota e WhatsApp"
    Write-Host ""
    Write-Host "Nenhum commit, push ou deploy foi criado."
}
catch {
    Restore-DeliveriesBackup
    Remove-Item -LiteralPath $Backup -Force -ErrorAction SilentlyContinue
    throw
}
